const { PrismaClient } = require('@prisma/client');
const p = new PrismaClient();
(async () => {
  const server = await p.server.findFirst({
    where: { OR: [{ vmid: 115 }, { hostname: { contains: 'bujangsmp', mode: 'insensitive' } }] },
    include: { dedicatedIp: true, portForwards: true, node: { select: { name: true, publicIp: true } } }
  });
  console.log(JSON.stringify(server, (k,v) => typeof v === 'bigint' ? v.toString() : v, 2));
  await p.\$disconnect();
})();
"

cd /opt/nxeon && node -e "
const { PrismaClient } = require('@prisma/client');
const p = new PrismaClient();
(async () => {
  // Subdomain collision check
  const paid = await p.server.findMany({ where: { subdomain: { not: null } }, select: { subdomain: true, hostname: true, status: true, wantsDedicatedIp: true } });
  const free = await p.freeMinecraftServer.findMany({ where: { subdomain: { not: null } }, select: { subdomain: true, name: true, status: true } });
  console.log('=== PAID SUBDOMAINS ===');
  paid.forEach(s => console.log(s.subdomain, s.hostname, s.status, 'dedicatedIp:', s.wantsDedicatedIp));
  console.log('=== FREE SUBDOMAINS ===');
  free.forEach(s => console.log(s.subdomain, s.name, s.status));

  // Check for collisions
  const paidSubs = new Set(paid.map(s => s.subdomain));
  const freeSubs = new Set(free.map(s => s.subdomain));
  const collisions = [...paidSubs].filter(s => freeSubs.has(s));
  console.log('=== COLLISIONS ===');
  console.log(collisions.length ? collisions : 'NONE');

  // IP pool status
  const ipPool = await p.dedicatedIp.groupBy({ by: ['status', 'purpose'], _count: true });
  console.log('=== IP POOL ===');
  ipPool.forEach(g => console.log(g.status, g.purpose, g._count));

  await p.\$disconnect();
})();
"

