    FROM \"Server\" s WHERE s.subdomain IS NOT NULL AND s.subdomain != ''
    UNION ALL
    SELECT 'free' as type, f.subdomain, f.name, f.status::text, 'false'
    FROM \"FreeMinecraftServer\" f WHERE f.subdomain IS NOT NULL AND f.subdomain != ''
