1	// Shared game-server order core — the ONE audited debit path for game servers,
2	// used by the wallet flow (lib/actions-gameplans.ts payAndDeployGame /
3	// orderGameServer) AND the Stripe confirm/webhook fulfilment (lib/fulfil-checkout.ts)
4	// so a card-paid game order provisions through the SAME machinery a VPS order does.
5	// Plain server module (NOT "use server") — no secrets, callable from actions,
6	// server components and the worker/webhook alike.
7	//
8	// This is the game analogue of lib/order.ts (orderQuote / placeOrder). It was
9	// factored OUT of the original `orderGameServer` so the card path and the wallet
10	// path settle through one function instead of two copies that could drift.
11	//
12	// MONEY RULES (audited):
13	//   - Prices are strictly DB-fed: `gamePlan.priceCents` is the ONLY source, priced
14	//     through the SAME `termPriceCents` formula the deploy wizard shows and the
15	//     renewal sweep bills (displayed === charged === renewed).
16	//   - Game bills FULL from month 1. There is NO first-month-free on game (that promo
17	//     is Shared-Web-Hosting-only); no $0 path, no coupon, no VAT change here.
18	//   - The wallet is the single debit; `debitWallet` refuses to overdraw.
19	//   - `sold` (card path) carries the price the order was SOLD at, stamped BEFORE the
20	//     card cleared, so fulfilment never re-prices after the money moved (the H2
21	//     incident guarded on lib/order.ts OrderPrice).
22	import { Prisma } from "@prisma/client";
23	import type { User } from "@prisma/client";
24	import { db } from "./db";
25	import { debitWallet, InsufficientBalanceError } from "./wallet";
26	import { addMonths, normalizeProductTerm, termPriceCents, vpsTerm } from "./billing-terms";
27	import { annualDiscountPct } from "./annual-discount";
28	import { capacityCheck } from "./capacity";
29	import { scheduleNode } from "./node-capacity";
30	import { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";
31	import { GAME_FAMILIES, type GameFamily } from "./games";
32	import { schemaFor, isValidVariant, validateConfig } from "./game-config";
33	import { recordDeployFunnelComplete } from "./deploy-funnel";
34	import { getSettingBool, getSettingInt } from "./settings";
35	import { invoiceCreateData, invoiceBranding, formatInvoiceNumber } from "./invoices";
36	import { validateSubdomainFormat, isSubdomainAvailable } from "./game-subdomain";
37	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
