41	/**
42	 * Feature + capacity gate shared by every game order entry point: the game-servers
43	 * feature can be switched off platform-wide (flag), and game servers are Server rows
44	 * too so they count toward the per-user cap. Returns a customer-facing error to
45	 * surface, or null to proceed.
46	 *
47	 * Lives in this PLAIN module (not lib/actions-gameplans.ts, which is `"use
48	 * server"`) rather than being exported from there, even though it is only ever
49	 * called with an already-authenticated `user` — a function that takes an
50	 * arbitrary `User`-shaped argument and does no session check of its own is
51	 * exactly what test/auth-lockouts.test.ts's "HAZARD" suite exists to catch the
52	 * moment it is exported from a Server Actions file: every export of such a file
53	 * is a public network endpoint, and this one would let a stranger probe any
54	 * userId's server count with no authentication at all. `lib/actions-gameplans.ts`
55	 * (payAndDeployGame, orderGameServer) and lib/actions-payment-providers.ts
56	 * (PayPal/Coinbase game-order creation) both call this AFTER their own
57	 * `requireUser()` — the guard the network-facing wrapper is responsible for.
58	 */
59	export async function gameOrderGate(user: User): Promise<string | null> {
60	  if (!(await getSettingBool("feature_game_servers", true))) {
61	    return "Game servers aren't available right now.";
62	  }
63	  const cap = await getSettingInt("max_servers_per_user", 10);
64	  if (cap > 0) {
65	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
66	    if (owned >= cap) {
67	      return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.`;
68	    }
69	  }
70	  return null;
71	}
