73	/** Extract a GameOrderIntent from a deploy form — shared by the wallet/card wizard
74	 *  action (lib/actions-gameplans.ts) and the PayPal/Coinbase order-creation actions
75	 *  (lib/actions-payment-providers.ts), so both parse the SAME form shape. Pure —
76	 *  lives in this plain module for the same "don't export a non-guarding helper from
77	 *  a Server Actions file" reason `gameOrderGate` above documents. */
78	export function gameIntentFromFormData(formData: FormData): GameOrderIntent {
79	  let config: Record<string, unknown> | null = null;
80	  const rawConfig = formData.get("config");
81	  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
82	    try {
83	      const parsed = JSON.parse(rawConfig);
84	      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
85	    } catch {
86	      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
87	      // fills defaults. It can never widen the charge (game is a flat term price).
88	      config = null;
89	    }
90	  }
91	  return {
92	    gamePlanId: String(formData.get("gamePlanId") ?? ""),
93	    termMonths: Number(formData.get("termMonths") ?? 1),
94	    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
95	    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
96	    variant: String(formData.get("variant") ?? "").trim() || undefined,
97	    subdomain: String(formData.get("subdomain") ?? "").trim().toLowerCase() || undefined,
98	    dedicatedIp: formData.get("dedicatedIp") === "1",
99	    config,
100	  };
101	}
