103	/** Hostname rules mirror the VPS order path (lib/order.ts orderSchema). */
104	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
105	
106	/** Short random suffix so auto-generated hostnames don't collide. */
107	export function randSuffix(n = 6): string {
108	  return Math.random().toString(36).slice(2, 2 + n);
109	}
