111	/**
112	 * The customer's full game-order intent — the tier, the billing term and the
113	 * per-game setup captured by the wizard. `config` holds the raw gameplay values
114	 * (validated against the family schema in `gameOrderQuote`); `variant` is the
115	 * server type/loader.
116	 */
117	export type GameOrderIntent = {
118	  gamePlanId: string;
119	  /** 1 (Monthly) or 12 (Annual) — normalised through normalizeProductTerm. */
120	  termMonths: number;
121	  /** Optional customer-facing nickname → Server.label. */
122	  serverName?: string;
123	  /** DNS-safe hostname → Server.name/hostname. Blank => auto-generated. */
124	  hostname?: string;
125	  /** Game type/loader id (e.g. "paper", "carbon"); validated per family. */
126	  variant?: string;
127	  /** Minecraft only: `<subdomain>.play.nxeon.cloud` — see lib/game-subdomain.ts. Required for minecraft orders. */
128	  subdomain?: string;
129	  /** Whether the customer opted for a dedicated IPv4 (paid addon). */
130	  dedicatedIp?: boolean;
131	  /** Raw gameplay settings; validated + coerced against the family schema. */
132	  config?: Record<string, unknown> | null;
133	};
134	
135	/**
136	 * The price a game order was SOLD at, stamped onto the Stripe session BEFORE the
137	 * card was charged and read back at fulfilment. Game has no promo/coupon/tax, so
138	 * this is just the net charge — a deliberately tiny shape (compare lib/order.ts
139	 * OrderPrice, which must also carry promo + VAT).
140	 */
141	export type GameOrderPrice = { chargeCents: number };
142	
143	/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
144	export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
145	  let obj: unknown = raw;
146	  if (typeof raw === "string") {
147	    try {
148	      obj = JSON.parse(raw);
149	    } catch {
150	      return null;
151	    }
152	  }
153	  if (!obj || typeof obj !== "object") return null;
154	  const { chargeCents } = obj as Record<string, unknown>;
155	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
156	  return { chargeCents };
157	}
