159	export type GameOrderQuote = {
160	  gamePlanId: string;
161	  gameFamily: string;
162	  planName: string;
163	  basePlanId: string;
164	  /** The base plan's RAM — fed to scheduleNode() to pick a node, same as VPS orders. */
165	  ramMB: number;
166	  osTemplateId: string;
167	  /** Normalised term (1 or 12). */
168	  term: number;
169	  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
170	  annualPct: number;
171	  /** DB-fed per-month base (priceCents / termMonths). */
172	  monthlyCents: number;
173	  /** The net charge for the whole term — displayed === charged === renewed. */
174	  chargeCents: number;
175	  hostname: string;
176	  label: string | null;
177	  variant: string;
178	  /** Minecraft only: the validated, available `<subdomain>.play.nxeon.cloud` label. Null for every other family. */
179	  subdomain: string | null;
180	  /** Whether the customer opted for a dedicated IPv4. */
181	  dedicatedIp: boolean;
182	  /** The dedicated-IP surcharge included in `chargeCents` (0 when not opted in). */
183	  ipCents: number;
184	  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
185	  values: Record<string, string | number | boolean>;
186	};
