188	/**
189	 * Validate + price a game order without placing it. Throws GameOrderError on any
190	 * problem. Pure of side effects beyond reads. The price is the whole truth about
191	 * what this order costs; the caller (wallet split, review step, checkout stamp)
192	 * quotes from THIS so what the customer sees is what settles.
193	 */
194	export async function gameOrderQuote(intent: GameOrderIntent): Promise<GameOrderQuote> {
195	  const term = normalizeProductTerm(intent.termMonths);
196	
197	  const gp = await db.gamePlan.findUnique({
198	    where: { id: intent.gamePlanId },
199	    include: { basePlan: true },
200	  });
201	  // A ONE-OFF CUSTOM game tier (lib/custom-plan.ts createCustomGamePlan, "build a
202	  // custom server") and its backing base Plan are both deliberately created
203	  // `active: false` — see the matching comment on lib/order.ts orderQuote's own
204	  // gate for why (30+ untouched `where: { active: true }` catalog queries across
205	  // this codebase must never surface either row generically). `sortOrder` is the
206	  // marker reserved for exactly this row shape, accepted here as an alternative.
207	  if (!gp || (!gp.active && gp.sortOrder !== CUSTOM_PLAN_SORT_ORDER)) {
208	    throw new GameOrderError("That game plan isn't available.");
209	  }
210	  if (!gp.basePlan?.active && gp.basePlan?.sortOrder !== CUSTOM_PLAN_SORT_ORDER) {
211	    throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
212	  }
213	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
214	    throw new GameOrderError("Unknown game family.");
215	  }
216	
217	  // Resolve the game image: the tier's own OsTemplate, else any active image for
218	  // this family. A game server can't provision without an image.
219	  let osTemplateId = gp.osTemplateId;
220	  if (osTemplateId) {
221	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
222	    if (!os?.active) osTemplateId = null;
223	  }
224	  if (!osTemplateId) {
225	    const os = await db.osTemplate.findFirst({
226	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
227	      orderBy: { sortOrder: "asc" },
228	    });
229	    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
230	    osTemplateId = os.id;
231	  }
232	
233	  // Hostname: validate a provided one strictly, else auto-generate a safe one.
234	  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
235	  let hostname = rawHost;
236	  if (hostname === "") {
237	    hostname = `${gp.gameFamily}-${randSuffix()}`;
238	  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
239	    throw new GameOrderError(
240	      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
241	    );
242	  }
243	
244	  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;
245	
246	  // Per-game setup: variant + gameplay settings, validated against the family
247	  // schema. Families without a customization schema (e.g. Terraria) carry no
248	  // variant and no gameplay values — the wizard shows only identity fields for them.
249	  const schema = schemaFor(gp.gameFamily);
250	  let variant = "";
251	  let values: Record<string, string | number | boolean> = {};
252	  if (schema) {
253	    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
254	    if (!isValidVariant(gp.gameFamily, variant)) {
255	      throw new GameOrderError("Choose a valid server type for this game.");
256	    }
257	    const res = validateConfig(gp.gameFamily, intent.config ?? {});
258	    if (!res.ok) throw new GameOrderError(res.error);
259	    values = res.values;
260	  }
261	
262	  // Minecraft-only: a customer-chosen `<subdomain>.play.nxeon.cloud`, required at
263	  // checkout (see lib/game-subdomain.ts — the free tier's own name rules, shared
264	  // so the two products can never disagree on what's valid or taken). Every other
265	  // family has no SRV-record connect story, so this stays null for them.
266	  let subdomain: string | null = null;
267	  if (gp.gameFamily === "minecraft") {
268	    const sub = (intent.subdomain ?? "").trim().toLowerCase();
269	    if (!sub) throw new GameOrderError("Pick a subdomain for your server — this is how players will connect.");
270	    const formatError = validateSubdomainFormat(sub);
271	    if (formatError) throw new GameOrderError(formatError);
272	    if (!(await isSubdomainAvailable(sub))) throw new GameOrderError("That subdomain is taken — try another.");
273	    subdomain = sub;
274	  }
275	
276	  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
277	  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
278	  // divisor keeps the maths correct if a multi-month base plan is ever configured.
279	  const annualPct = await annualDiscountPct();
280	  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
281	  const wantIp = !!intent.dedicatedIp;
282	  const ipCents = wantIp ? (await dedicatedIpMonthlyCents()) * term : 0;
283	  const chargeCents = termPriceCents(monthlyCents, term, annualPct) + ipCents;
284	
285	  return {
286	    gamePlanId: gp.id,
287	    gameFamily: gp.gameFamily,
288	    planName: gp.name,
289	    basePlanId: gp.basePlanId,
290	    ramMB: gp.basePlan.ramMB,
291	    osTemplateId,
292	    term,
293	    annualPct,
294	    monthlyCents,
295	    chargeCents,
296	    hostname,
297	    label,
298	    variant,
299	    subdomain,
300	    dedicatedIp: wantIp,
301	    ipCents,
302	    values,
303	  };
304	}
305	
306	/**
307	 * Place a game order: re-validate + price, capacity-check, then atomically debit
308	 * the wallet and create the Server (sized by the tier's base VPS plan, running the
309	 * game image, with the customer's variant + gameplay settings) plus a PROVISION
310	 * job. Returns the new server id. Does NOT redirect.
311	 *
312	 * `sold` (card path) overrides the recomputed price with the one the order was
313	 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
314	 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
315	 * the customer consented to instead of re-pricing against a rate that changed in
316	 * between. The wallet path omits it and pays the fresh quote it computed moments
317	 * ago. This mirrors `sold` in lib/order.ts placeOrder.
318	 *
319	 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
320	 * path is gated by the balance check in the action). This still enforces the
321	 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
322	 */
323	export async function placeGameOrder(
324	  user: User,
325	  intent: GameOrderIntent,
326	  sold?: GameOrderPrice | null,
327	): Promise<string> {
328	  const quote = await gameOrderQuote(intent);
329	
330	  // Bill off the SOLD price when present (never re-priced after the card cleared),
331	  // else the fresh quote. Game has no promo/coupon, so this scalar is the whole
332	  // truth about what this order costs.
333	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
334	
335	  // Oversell guard — the VPS order path enforces this; game orders must too, or a
336	  // game server could commit host RAM past capacity.
337	  const capacity = await capacityCheck(quote.basePlanId);
338	  if (!capacity.ok) {
339	    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
340	  }
341	
342	  // Pick a node the same way a VPS order does — without this, every game
343	  // server's `nodeId` stays null and `worker/index.ts`'s `nodeFor()` fallback
344	  // (`server.node ?? primary node`) pins EVERY game server onto the primary
345	  // node forever, regardless of its actual load. Confirmed live: every game
346	  // server in production had nodeId: null and primary sat at 84% real RAM /
347	  // 200% committed CPU while other nodes were comparatively idle.
348	  const node = await scheduleNode(quote.ramMB);
349	
350	  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
351	  // path the wallet was credited the card leg first, so this holds.
352	  if (user.balanceCents < chargeCents) {
353	    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
354	  }
355	
356	  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
357	  const termLabel =
358	    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;
359	
360	  // Line-item description shared by the wallet-transaction memo and the invoice —
361	  // mirrors lib/order.ts's VPS line ("<plan> VPS (<hostname>) — <term>"), the
362	  // pattern lib/actions-hosting.ts and lib/actions-email-hosting.ts also follow.
363	  const invDesc = `${quote.planName} Game Server (${quote.hostname}) — ${termLabel}`;
364	
365	  let server;
366	  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
367	  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
368	  // null and emails nothing. Mirrors `orderInvoice` in lib/order.ts placeOrder.
369	  let orderInvoice: { id: string; number: number; amountCents: number } | null = null;
370	  try {
371	    server = await db.$transaction(async (tx) => {
372	      await debitWallet(tx, user.id, chargeCents);
373	      await tx.walletTransaction.create({
374	        data: {
375	          userId: user.id,
376	          amountCents: -chargeCents,
377	          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
378	        },
379	      });
380	      // Billing document for the charge — created inside the same debit tx so it
381	      // shares the transaction's atomicity (a rolled-back charge leaves no invoice),
382	      // exactly like lib/order.ts's VPS invoice and worker/billing.ts's renewal
383	      // invoice. Game has no promo/coupon/tax (see GameOrderPrice), so this is a
384	      // single line for the full charge.
385	      const createdInvoice = await tx.invoice.create({
386	        data: invoiceCreateData({
387	          userId: user.id,
388	          description: invDesc,
389	          status: "PAID",
390	          taxCents: 0,
391	          taxRatePercent: 0,
392	          taxCountry: null,
393	          period: { start: new Date(), end: addMonths(new Date(), quote.term) },
394	          lineItems: [{ description: invDesc, qty: 1, unitCents: chargeCents, amountCents: chargeCents }],
395	        }),
396	      });
397	      orderInvoice = {
398	        id: createdInvoice.id,
399	        number: createdInvoice.number,
400	        amountCents: createdInvoice.amountCents,
401	      };
402	      const s = await tx.server.create({
403	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
404	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
405	        data: {
406	          name: quote.hostname,
407	          hostname: quote.hostname,
408	          label: quote.label,
409	          userId: user.id,
410	          planId: quote.basePlanId,
411	          gamePlanId: quote.gamePlanId,
412	          osTemplateId: quote.osTemplateId,
413	          // The customer's per-game setup, applied at the point of sale — the worker
414	          // renders these into the game's own config at provision (worker/game-config).
415	          gameVariant: quote.variant || null,
416	          subdomain: quote.subdomain,
417	          gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
418	          // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
419	          // game branch renews monthlyCents × termMonths × (1 − annual).
420	          termMonths: quote.term,
421	          // No seasonal promo on game — this term was sold at 0% off, so any future
422	          // proration prices against full price.
423	          termPromoPercent: 0,
424	          // The annual rate frozen at sale, so the renewal bills the SAME price the
425	          // order charged even if the admin retunes annual_discount_percent later.
426	          annualDiscountPct: quote.annualPct,
427	          nodeId: node?.id ?? null,
428	          wantsDedicatedIp: quote.dedicatedIp,
429	          expiresAt: addMonths(new Date(), quote.term),
430	        } as Prisma.ServerUncheckedCreateInput,
431	      });
432	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
433	      return s;
434	    });
435	  } catch (e) {
436	    if (e instanceof InsufficientBalanceError) {
437	      throw new GameOrderError("Insufficient balance. Top up your wallet first.");
438	    }
439	    // Narrow race: another order claimed the same subdomain between the
440	    // isSubdomainAvailable check above and this insert (or the free tier just
441	    // claimed the same name in the other table's own concurrent request).
442	    if ((e as { code?: string })?.code === "P2002") {
443	      throw new GameOrderError("That subdomain was just taken — go back and pick another.");
444	    }
445	    throw e;
446	  }
447	
448	  await db.auditLog.create({
449	    data: {
450	      userId: user.id,
451	      action: "gameserver.order",
452	      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
453	    },
454	  });
455	  // Deploy-funnel COMPLETION — the game analogue of lib/order.ts placeOrder. The ONE
456	  // place a game order is created & paid, reached by BOTH the wallet path
