4	/**
5	 * DNS for PAID Minecraft server subdomains (`<name>.play.nxeon.cloud`).
6	 *
7	 * Distinct from lib/cloudflare-dns.ts, which is built for CUSTOMER-supplied
8	 * Cloudflare tokens against a CUSTOMER's own zone. This module uses Nxeon's
9	 * own platform token (CLOUDFLARE_DNS_API_TOKEN — already live in production,
10	 * see worker/hosting.ts's ensureWildcardCert) against Nxeon's own nxeon.cloud
11	 * zone, and manages SRV records, which lib/cloudflare-dns.ts's CfRecordType
12	 * doesn't support. It still reuses that module's cfRequest/cfFindZoneId (the
13	 * generic, token-as-parameter HTTP+auth plumbing) rather than duplicating it.
14	 *
15	 * Free-tier Minecraft servers (FreeMinecraftServer) reuse the SAME
16	 * play.nxeon.cloud domain via one shared wildcard A record + mc-router —
17	 * this module's exact-name records simply take DNS precedence over that
18	 * wildcard for the specific names paid customers claim (ordinary DNS
19	 * specificity, no coordination needed with the free-tier setup).
20	 *
21	 * Opt-in + inert, matching ensureWildcardCert's own gating: every export is a
22	 * silent no-op when CLOUDFLARE_DNS_API_TOKEN isn't set, so this can never
23	 * become a hard dependency for provisioning, a port-forward save, or a
24	 * suspend/unsuspend cycle.
25	 */
26	
27	let cachedZoneId: string | null | undefined;
28	
29	function token(): string {
30	  return String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
31	}
32	
33	async function zoneId(): Promise<string | null> {
34	  if (cachedZoneId !== undefined) return cachedZoneId;
35	  cachedZoneId = await cfFindZoneId(token(), "nxeon.cloud");
36	  return cachedZoneId;
37	}
38	
39	/** The shared base domain both free and paid Minecraft subdomains live under. */
40	export async function gameSubdomainBase(): Promise<string> {
41	  return getSetting("free_minecraft_domain", "play.nxeon.cloud");
42	}
43	
44	type SrvRecord = { id: string; type: string; name: string; data?: { priority: number; weight: number; port: number; target: string } };
45	
46	async function upsertA(zone: string, name: string, ip: string): Promise<void> {
47	  const existing = await cfRequest<{ id: string }[]>(token(), "GET", `/zones/${zone}/dns_records?type=A&name=${encodeURIComponent(name)}&per_page=5`);
48	  const body = { type: "A", name, content: ip, ttl: 1, proxied: false };
49	  if (existing[0]) {
50	    await cfRequest(token(), "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
51	  } else {
52	    await cfRequest(token(), "POST", `/zones/${zone}/dns_records`, body);
53	  }
54	}
55	
56	/**
57	 * `host` is the bare `<subdomain>.<base>` name. Confirmed live against the
58	 * Cloudflare API (2026-08-30, throwaway test record, deleted immediately
59	 * after): unlike A/MX/TXT, Cloudflare wants the FULL prefixed name
60	 * (`_minecraft._tcp.<host>`) as the top-level `name`, with `data` holding
61	 * ONLY `{priority, weight, port, target}` — `service`/`proto`/`name` inside
62	 * `data` (a shape that's floated around in various docs/examples) is
63	 * REJECTED with "DNS name is invalid" (code 9000). `target` is the A
64	 * record's own name (`host`), matching the pattern established above.
65	 */
66	async function upsertSrv(zone: string, host: string, target: string, port: number): Promise<void> {
67	  const srvName = `_minecraft._tcp.${host}`;
68	  const existing = await cfRequest<SrvRecord[]>(token(), "GET", `/zones/${zone}/dns_records?type=SRV&name=${encodeURIComponent(srvName)}&per_page=5`);
69	  const body = { type: "SRV", name: srvName, data: { priority: 0, weight: 5, port, target } };
70	  if (existing[0]) {
71	    await cfRequest(token(), "PUT", `/zones/${zone}/dns_records/${existing[0].id}`, body);
72	  } else {
73	    await cfRequest(token(), "POST", `/zones/${zone}/dns_records`, body);
74	  }
75	}
76	
77	/**
78	 * Create or update the A + SRV pair for `<subdomain>.<base>` -> `ip:port`.
79	 * Silent no-op if the platform Cloudflare token isn't configured.
80	 */
81	export async function upsertMinecraftSubdomainDns(opts: { subdomain: string; ip: string; port: number }): Promise<void> {
82	  if (!token()) return;
83	  const zone = await zoneId();
84	  if (!zone) return;
85	  const base = await gameSubdomainBase();
86	  const host = `${opts.subdomain}.${base}`;
87	  await upsertA(zone, host, opts.ip);
88	  await upsertSrv(zone, host, host, opts.port);
89	}
90	
91	/**
92	 * Delete both records for `<subdomain>.<base>`, if present. Idempotent —
93	 * tolerant of records already missing (nothing to clean up).
94	 */
95	export async function deleteMinecraftSubdomainDns(subdomain: string): Promise<void> {
96	  if (!token()) return;
97	  const zone = await zoneId();
98	  if (!zone) return;
99	  const base = await gameSubdomainBase();
100	  const host = `${subdomain}.${base}`;
101	  const [aRecords, srvRecords] = await Promise.all([
102	    cfRequest<{ id: string }[]>(token(), "GET", `/zones/${zone}/dns_records?type=A&name=${encodeURIComponent(host)}&per_page=5`),
103	    cfRequest<{ id: string }[]>(token(), "GET", `/zones/${zone}/dns_records?type=SRV&name=${encodeURIComponent(`_minecraft._tcp.${host}`)}&per_page=5`),
104	  ]);
105	  for (const r of [...aRecords, ...srvRecords]) {
106	    await cfRequest(token(), "DELETE", `/zones/${zone}/dns_records/${r.id}`);
107	  }
108	}
